    {"name":"write","arguments":{"path":"src/lib.rs","overwrite":True,"content":"use std::collections::HashMap;\n\npub fn lowest_price(books: &[u32]) -> u32 {\n    let mut counts = [0u32; 5];\n    for &book in books {\n        if (1..=5).contains(&book) { counts[(book - 1) as usize] += 1; }\n    }\n    fn solve(counts: [u32; 5], memo: &mut HashMap<[u32; 5], u32>) -> u32 {\n        if counts.iter().all(|&n| n == 0) { return 0; }\n        if let Some(&cost) = memo.get(&counts) { return cost; }\n        let available: Vec<usize> = (0..5).filter(|&i| counts[i] > 0).collect();\n        let mut best = u32::MAX;\n        for mask in 1usize..(1usize << available.len()) {\n            let size = mask.count_ones() as u32;\n            let mut next = counts;\n            for (bit, &index) in available.iter().enumerate() {\n                if mask & (1 << bit) != 0 { next[index] -= 1; }\n            }\n            let unit_cost = match size { 1 => 800, 2 => 1520, 3 => 2160, 4 => 2560, 5 => 3000, _ => unreachable!() };\n            best = best.min(unit_cost + solve(next, memo));\n        }\n        memo.insert(counts, best);\n        best\n    }\n    solve(counts, &mut HashMap::new())\n}\n"}},
